import React, { useState } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  const detectSource = (transactions, backendType) => {
    if (backendType && backendType !== "unknown") return backendType;

    const sample = transactions?.[0]?.description?.toLowerCase() || "";

    if (sample.includes("gpay") || sample.includes("upi")) return "GPay";
    if (sample.includes("phonepe")) return "PhonePe";
    if (sample.includes("paytm")) return "Paytm";

    return "Bank Statement";
  };

  const handleUpload = async () => {
    if (!file) return alert("Please select a PDF file");

    setLoading(true);

    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("http://localhost:8000/upload-statement/", {
        method: "POST",
        body: formData,
      });

      const data = await res.json();

      const finalSource = detectSource(
        data.transactions,
        data.detected_type
      );

      setTransactions(data.transactions || []);
      setType(finalSource);

      const history = JSON.parse(localStorage.getItem("history")) || [];

      history.unshift({
        date: new Date().toLocaleString(),
        type: finalSource,
        count: data.transactions?.length || 0,
        transactions: data.transactions || [],
      });

      localStorage.setItem("history", JSON.stringify(history));
    } catch {
      alert("Upload failed");
    }

    setLoading(false);
  };

  const historyData = JSON.parse(localStorage.getItem("history")) || [];

  const deleteHistory = (index) => {
    const updated = [...historyData];
    updated.splice(index, 1);
    localStorage.setItem("history", JSON.stringify(updated));
    window.location.reload();
  };

  const viewHistory = (item) => {
    setTransactions(item.transactions || []);
    setType(item.type || "");
    setActiveTab("overview");
  };

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* NAVBAR */}
        <div className="navbar">
          <div className="logo">FinSight</div>

          <div className="nav-actions">
            <div className="tabs">
              <span
                className={`tab ${activeTab === "overview" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("overview")}
              >
                Overview
              </span>

              <span
                className={`tab ${activeTab === "history" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("history")}
              >
                History
              </span>
            </div>

            {/* PREMIUM PROFILE ICON */}
            <div
              onClick={() => setShowProfile(!showProfile)}
              style={{
                width: "42px",
                height: "42px",
                borderRadius: "50%",
                background: "linear-gradient(135deg, #667eea, #764ba2)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                cursor: "pointer",
                marginLeft: "12px",
                boxShadow: "0 6px 14px rgba(0,0,0,0.2)",
                fontSize: "20px",
                color: "#fff"
              }}
            >
              👤
            </div>

            <div
              className={`theme-circle ${darkMode ? "dark" : "light"}`}
              onClick={() => setDarkMode(!darkMode)}
            ></div>
          </div>
        </div>

        {/* PROFILE DROPDOWN */}
        {showProfile && (
          <div className="card" style={{ marginTop: "12px" }}>
            <h3>User Profile</h3>
            <p><b>Name:</b> User</p>
            <p><b>Email:</b> user@email.com</p>
          </div>
        )}

        {/* HERO (PREMIUM FIXED) */}
        <div className="hero" style={{ marginBottom: "25px" }}>
          <h1 style={{
            fontSize: "34px",
            fontWeight: "700",
            letterSpacing: "0.6px",
            marginBottom: "8px"
          }}>
            Welcome back,
            <span style={{ color: "#2f4b7c", marginLeft: "8px" }}>
              User
            </span>
          </h1>

          <p style={{
            fontSize: "15px",
            opacity: 0.7,
            letterSpacing: "0.3px"
          }}>
            Personal Expense Intelligence Dashboard
          </p>
        </div>

        {/* OVERVIEW ONLY */}
        {activeTab === "overview" && (
          <>
            {/* KPI */}
            <div className="kpi-grid">
              <div className="kpi-card">
                <h4>Statement Source</h4>
                <p>{type || "Not uploaded"}</p>
              </div>

              <div className="kpi-card">
                <h4>Total Transactions</h4>
                <p>{transactions?.length || 0}</p>
              </div>

              <div className="kpi-card">
                <h4>Status</h4>
                <p>{transactions?.length ? "Processed" : "Waiting"}</p>
              </div>
            </div>

            <div className="top-section">
              <div className="card upload-card">
                <h3>Upload Statement</h3>

                <div className="upload-row">
                  <input
                    type="file"
                    accept=".pdf"
                    onChange={(e) => setFile(e.target.files[0])}
                  />
                  <button onClick={handleUpload}>
                    Analyze Statement
                  </button>
                </div>

                {loading && (
                  <p style={{ marginTop: "10px" }}>
                    Processing... Please wait ⏳
                  </p>
                )}
              </div>

              <div className="card summary-card">
                <h3>Insights Summary</h3>
                <p>
                  AI-powered transaction analysis with smart categorization
                </p>
              </div>
            </div>

            {/* TRANSACTION TABLE */}
            {transactions.length > 0 && (
              <div className="card table-card">
                <h3>Transaction Ledger</h3>

                <div className="table-wrapper">
                  <table>
                    <thead>
                      <tr>
                        <th>Date</th>
                        <th>Type</th>
                        <th>Description</th>
                        <th>Category</th>
                        <th>Need/Want</th>
                        <th>Amount</th>
                      </tr>
                    </thead>

                    <tbody>
                      {transactions.map((txn, i) => (
                        <tr key={i}>
                          <td>{txn.date}</td>
                          <td className={txn.type === "debit" ? "debit" : "credit"}>
                            {txn.type}
                          </td>
                          <td>{txn.description}</td>
                          <td>{txn.category || "Other"}</td>
                          <td>{txn.need_want || "Other"}</td>
                          <td>₹{txn.amount}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </>
        )}

        {/* CLEAN HISTORY TAB (NO KPI) */}
        {activeTab === "history" && (
          <div className="card table-card">
            <h3>Upload History</h3>

            <div className="table-wrapper">
              <table>
                <thead>
                  <tr>
                    <th>Date</th>
                    <th>Source</th>
                    <th>Transactions</th>
                    <th style={{ textAlign: "right" }}>Actions</th>
                  </tr>
                </thead>

                <tbody>
                  {historyData.map((h, i) => (
                    <tr key={i}>
                      <td>{h.date}</td>
                      <td>{h.type}</td>
                      <td>{h.count}</td>

                      <td style={{ textAlign: "right" }}>
                        <button onClick={() => viewHistory(h)}>View</button>
                        <button
                          onClick={() => deleteHistory(i)}
                          style={{ marginLeft: "10px" }}
                        >
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

export default Dashboard;
